def detect_llms():
    # Try to detect available LLMs via Ollama API
    try:
        resp = pyrequests.get('http://localhost:11434/api/tags', timeout=3)
        resp.raise_for_status()
        tags = resp.json().get('models', [])
        return [m['name'] for m in tags]
    except Exception:
        return []


def setup_wizard():
    clear_screen()
    console.print(Panel("[bold cyan]Omnitide Setup & Workflow Wizard[/bold cyan]", subtitle="Guided Configuration", box=box.DOUBLE))
    console.print("\n[bold]Welcome! This wizard will help you set up, configure, and understand all workflows in this project.[/bold]\n")
    # Docker check
    import shutil
    if not shutil.which("docker"):
        console.print("[red]Docker is not installed or not in PATH. Please install Docker before continuing.[/red]")
        Prompt.ask("Press Enter to exit wizard")
        return
    else:
        console.print("[green]Docker is installed.[/green]")
    # Docker image check
    import docker
    client = docker.from_env()
    images = client.images.list()
    image_names = [tag for img in images for tag in img.tags]
    if not any("duo-project" in tag for tag in image_names):
        console.print("[yellow]Docker image 'duo-project' not found. Building now...")
        os.system("docker build -t duo-project .")
        console.print("[green]Docker image built.[/green]")
    else:
        console.print("[green]Docker image 'duo-project' found.")
    # LLM detection and selection
    llms = detect_llms()
    if llms:
        console.print("\n[bold]Available LLMs detected:[/bold]")
        for idx, llm in enumerate(llms, 1):
            console.print(f"  [{idx}] {llm}")
        llm_choice = Prompt.ask("Select LLM by number", choices=[str(i) for i in range(1, len(llms)+1)], default="1")
        selected_llm = llms[int(llm_choice)-1]
        set_key(LLM_ENV_PATH, "OLLAMA_MODEL", selected_llm)
        console.print(f"[green]Selected LLM: {selected_llm} (saved to .env)[/green]")
    else:
        console.print("[yellow]No LLMs detected via Ollama. Using default: gemma:2b")
        set_key(LLM_ENV_PATH, "OLLAMA_MODEL", "gemma:2b")
    # Explain main workflows
    console.print("\n[bold]Workflows available:[/bold]")
    console.print("- [cyan]Code Generation[/cyan]: Use LLMs to generate code from high-level descriptions.")
    console.print("- [cyan]Agent Execution[/cyan]: Run ExWork, Scribe, and other agents for automation, validation, and review.")
    console.print("- [cyan]Project Utilities[/cyan]: Git, cleaning, refactoring, and more.")
    console.print("- [cyan]Nexus Backend[/cyan]: Manage the backend server and Docker containers.")
    console.print("- [cyan]New Project Creation[/cyan]: Bootstrap a new project from this template.")
    console.print("\n[bold]All scripts and agents in the workspace will be auto-discovered and available from the menu.[/bold]")
    Prompt.ask("Press Enter to continue to the main menu")


def discover_scripts():
    # Discover all .py scripts in the workspace root (excluding hidden/venv/test folders)
    scripts = []
    cwd = os.getcwd()
    for fname in os.listdir(cwd):
        if fname.endswith(".py") and not fname.startswith(".") and fname not in ["setup_duo.sh"]:
            scripts.append(fname)
    return scripts


